from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Map value to index for quick lookup
        n = len(nums)
        parent = list(range(n))
        rank = [0]*n
        def find(x):
            while parent[x]!=x:
                parent[x]=parent[parent[x]]
                x=parent[x]
            return x
        def union(x,y):
            rx,ry=find(x),find(y)
            if rx==ry: return
            if rank[rx]<rank[ry]:
                parent[rx]=ry
            elif rank[rx]>rank[ry]:
                parent[ry]=rx
            else:
                parent[ry]=rx
                rank[rx]+=1
        # Collect indices with value <= threshold
        small_indices = [i for i,v in enumerate(nums) if v<=threshold]
        from collections import defaultdict
        mult_to_indices = defaultdict(list)
        for idx in small_indices:
            val = nums[idx]
            for m in range(val, threshold+1, val):
                mult_to_indices[m].append(idx)
        for lst in mult_to_indices.values():
            if len(lst)>1:
                base=lst[0]
                for other in lst[1:]:
                    union(base, other)
        roots=set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)

