from bisect import bisect_left


def kmp_find_all(text: str, pat: str):
    """Return list of start indices where pat occurs in text using KMP."""
    if not pat:
        # Empty pattern matches at all positions
        return list(range(len(text)+1))
    n, m = len(text), len(pat)
    # Build lps array
    lps = [0]*m
    length = 0
    i = 1
    while i < m:
        if pat[i] == pat[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length-1]
            else:
                lps[i] = 0
                i += 1
    # Search
    res = []
    i = 0  # index for text
    j = 0  # index for pat
    while i < n:
        if text[i] == pat[j]:
            i += 1
            j += 1
            if j == m:
                res.append(i - j)
                j = lps[j-1]
        else:
            if j != 0:
                j = lps[j-1]
            else:
                i += 1
    return res


class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        if len(parts) != 3:
            raise ValueError("Pattern must contain two '*'")
        a, b, c = parts
        n = len(s)
        best = 10**18

        # Get occurrence lists
        occ_a = kmp_find_all(s, a)
        occ_b = kmp_find_all(s, b)
        occ_c = kmp_find_all(s, c)

        # Special cases
        if not a and not b and not c:
            return 0
        if not a and not b:
            # only c
            return len(c)
        if not a and not c:
            return len(b)
        if not b and not c:
            return len(a)

        # General case
        # If a exists
        if a:
            pb = 0
            pc = 0
            for sa in occ_a:
                # advance pb to first b start >= sa+len(a)
                while pb < len(occ_b) and occ_b[pb] < sa + len(a):
                    pb += 1
                if pb == len(occ_b):
                    break
                sb = occ_b[pb]
                # advance pc to first c start >= sb+len(b)
                while pc < len(occ_c) and occ_c[pc] < sb + len(b):
                    pc += 1
                if pc == len(occ_c):
                    break
                sc = occ_c[pc]
                length = sc + len(c) - sa
                if length < best:
                    best = length
        elif b:
            pc = 0
            for sb in occ_b:
                while pc < len(occ_c) and occ_c[pc] < sb + len(b):
                    pc += 1
                if pc == len(occ_c):
                    break
                sc = occ_c[pc]
                length = sc + len(c) - sb
                if length < best:
                    best = length
        else:
            # a and b empty, only c
            best = len(c)

        return best if best != 10**18 else -1

if __name__ == "__main__":
    import sys, json
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit()
    s, p = data[0], data[1]
    print(Solution().shortestMatchingSubstring(s, p))

