import sys


class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, delta):
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    Q = int(next(it))
    H = [0] * (N + 1)
    for i in range(1, N + 1):
        H[i] = int(next(it))
    # previous greater to the left
    prev = [0] * (N + 1)
    stack = []  # indices with decreasing heights
    for i in range(1, N + 1):
        while stack and H[stack[-1]] < H[i]:
            stack.pop()
        prev[i] = stack[-1] if stack else 0
        stack.append(i)
    # bucket queries by r
    qs_by_r = [[] for _ in range(N + 1)]
    for qi in range(Q):
        l = int(next(it)); r = int(next(it))
        qs_by_r[r].append((l, qi))
    ans = [0] * Q
    bit = BIT(N)
    # iterate r from N down to 1
    for r in range(N, 0, -1):
        nxt = r + 1
        if nxt <= N:
            bit.add(prev[nxt] + 1, 1)
        for l, qi in qs_by_r[r]:
            # we need number of j > r with prev[j] < l
            # in BIT we have counts at position prev[j]+1
            # so prefix sum up to l gives indices <= l-1
            ans[qi] = bit.sum(l)
    sys.stdout.write("\n".join(map(str, ans)))


if __name__ == "__main__":
    solve()

