import random

def brute(H,l,r):
    N=len(H)-1
    cnt=0
    for j in range(r+1,N+1):
        if all(H[k] <= H[j] for k in range(l+1,j)) and all(H[k] <= H[j] for k in range(r+1,j)):
            cnt+=1
    return cnt

# Our efficient function using prev logic

def efficient(H,l,r):
    N=len(H)-1
    prev=[0]*(N+1)
    stack=[]
    for i in range(1,N+1):
        while stack and H[stack[-1]] < H[i]:
            stack.pop()
        prev[i] = stack[-1] if stack else 0
        stack.append(i)
    return sum(1 for j in range(r+1,N+1) if prev[j] < l)

for n in range(2,15):
    for _ in range(200):
        heights=list(range(1,n+1))
        random.shuffle(heights)
        H=[0]+heights
        for l in range(1,n):
            for r in range(l+1,n+1):
                if brute(H,l,r)!=efficient(H,l,r):
                    print('Mismatch',n,H,l,r,brute(H,l,r),efficient(H,l,r))
                    raise SystemExit
print('All good')

