import random, heapq

def solve_bruteforce(intervals, weights, s,t):
    N=len(intervals)
    adj=[[] for _ in range(N)]
    for i in range(N):
        L1,R1=intervals[i]
        for j in range(i+1,N):
            L2,R2=intervals[j]
            if R1< L2 or R2< L1:
                adj[i].append(j)
                adj[j].append(i)
    INF=10**18
    dist=[INF]*N
    dist[s]=weights[s]
    pq=[(dist[s],s)]
    while pq:
        d,u=heapq.heappop(pq)
        if d!=dist[u]: continue
        if u==t: return d
        for v in adj[u]:
            nd=d+weights[v]
            if nd<dist[v]:
                dist[v]=nd
                heapq.heappush(pq,(nd,v))
    return None

def min_left(intervals, weights, idx):
    Ls=intervals[idx][0]
    best=None
    for j,(lj,rj) in enumerate(intervals):
        if rj< Ls:
            if best is None or weights[j]<best:
                best=weights[j]
    return best

def min_right(intervals, weights, idx):
    Rs=intervals[idx][1]
    best=None
    for j,(lj,rj) in enumerate(intervals):
        if lj> Rs:
            if best is None or weights[j]<best:
                best=weights[j]
    return best


def min_between(intervals, weights, s,t):
    Ls,Rs=intervals[s]
    Lt,Rt=intervals[t]
    best=None
    for j,(lj,rj) in enumerate(intervals):
        if j in (s,t): continue
        if (Rs< lj or rj< Ls) and (Rt< lj or rj< Lt):
            if best is None or weights[j]<best:
                best=weights[j]
    return best

def fast_answer(intervals, weights, s,t):
    Ls,Rs=intervals[s]
    Lt,Rt=intervals[t]
    if Rs< Lt or Rt< Ls:
        return weights[s]+weights[t]
    best=float('inf')
    b=min_between(intervals,weights,s,t)
    if b is not None:
        best=b+weights[s]+weights[t]
    ml=min_left(intervals,weights,s)
    mr=min_right(intervals,weights,t)
    if ml is not None and mr is not None:
        best=min(best, ml+mr+weights[s]+weights[t])
    ml=min_left(intervals,weights,t)
    mr=min_right(intervals,weights,s)
    if ml is not None and mr is not None:
        best=min(best, ml+mr+weights[s]+weights[t])
    return best if best!=float('inf') else None

