def compute_ans2(inp):
    data=list(map(int,inp.split()))
    it=iter(data)
    N=next(it); X=next(it)-1
    A=[next(it) for _ in range(N)]
    B=[next(it) for _ in range(N)]
    P=[next(it)-1 for _ in range(N)]
    Q=[next(it)-1 for _ in range(N)]
    from collections import deque
    revP=[[] for _ in range(N)]; revQ=[[] for _ in range(N)]
    for i in range(N):revP[P[i]].append(i); revQ[Q[i]].append(i)
    visR=[False]*N; dq=deque([X]); visR[X]=True
    while dq:
        u=dq.popleft()
        for w in revP[u]:
            if not visR[w]: visR[w]=True; dq.append(w)
    visB=[False]*N; dq=deque([X]); visB[X]=True
    while dq:
        u=dq.popleft()
        for w in revQ[u]:
            if not visB[w]: visB[w]=True; dq.append(w)
    # compute forward reachable from initial balls except X
    start=[i for i in range(N) if (A[i] or B[i]) and i!=X]
    visF=[False]*N
    dq=deque(start)
    for s in start: visF[s]=True
    while dq:
        u=dq.popleft()
        for v in (P[u], Q[u]):
            if not visF[v]: visF[v]=True; dq.append(v)
    ans=0
    for i in range(N):
        if i!=X and (visR[i] or visB[i]) and visF[i]:
            ans+=1
    # impossible if any ball node not visited by either type (since not able to empty?)
    for i in range(N):
        if (A[i] or B[i]) and i!=X and not visF[i]:
            return -1
    return ans

