import sys, bisect

class AxisMap:
    def __init__(self):
        self.map = {}  # key -> list of coords
        self.parents = {}

    def add(self, key, val):
        self.map.setdefault(key, []).append(val)

    def finalize(self):
        for key, lst in self.map.items():
            lst.sort()
            # parent list length len(lst)+1
            self.parents[key] = list(range(len(lst)+1))

    def find(self, parent, i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def remove_and_count(self, key, lo, hi):
        if key not in self.map:
            return 0
        lst = self.map[key]
        parent = self.parents[key]
        l_idx = bisect.bisect_left(lst, lo)
        r_idx = bisect.bisect_right(lst, hi) - 1
        if l_idx > r_idx:
            return 0
        cnt = 0
        i = l_idx
        while i <= r_idx:
            i = self.find(parent, i)
            if i > r_idx:
                break
            cnt += 1
            parent[i] = i + 1
            i = parent[i]
        return cnt


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it)); M = int(next(it)); Sx = int(next(it)); Sy = int(next(it))
    y_map = AxisMap()
    x_map = AxisMap()
    for _ in range(N):
        x = int(next(it)); y = int(next(it))
        y_map.add(y, x)
        x_map.add(x, y)
    y_map.finalize(); x_map.finalize()
    x, y = Sx, Sy
    count = 0
    for _ in range(M):
        d = next(it)
        c = int(next(it))
        if d == 'U':
            ny = y + c
            count += y_map.remove_and_count(x, y+1, ny) if c > 0 else 0
            y = ny
        elif d == 'D':
            ny = y - c
            count += y_map.remove_and_count(x, ny, y-1) if c > 0 else 0
            y = ny
        elif d == 'R':
            nx = x + c
            count += x_map.remove_and_count(y, x+1, nx) if c > 0 else 0
            x = nx
        elif d == 'L':
            nx = x - c
            count += x_map.remove_and_count(y, nx, x-1) if c > 0 else 0
            x = nx
    print(x, y, count)

