import sys, collections

# BFS on pairs using forward edges from left and reverse edges from right

def solve():
    data=sys.stdin.read().strip().splitlines()
    if not data:
        return
    N=int(data[0])
    grid=[list(line.strip()) for line in data[1:1+N]]
    out_by_char=[[ [] for _ in range(26) ] for _ in range(N)]
    in_by_char=[[ [] for _ in range(26) ] for _ in range(N)]
    edges=[[None]*N for _ in range(N)]
    for i in range(N):
        for j,ch in enumerate(grid[i]):
            if ch!='-':
                edges[i][j]=ch
                out_by_char[i][ord(ch)-97].append(j)
                in_by_char[j][ord(ch)-97].append(i)
    # Precompute pair neighbors
    pair_neighbors=[[] for _ in range(N*N)]
    for u in range(N):
        for v in range(N):
            lst=[]
            for ci in range(26):
                if not out_by_char[u][ci] or not in_by_char[v][ci]:
                    continue
                for up in out_by_char[u][ci]:
                    for vp in in_by_char[v][ci]:
                        lst.append((up, vp))
            pair_neighbors[u*N+v]=lst
    ans=[[-1]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            start=i*N+j
            visited=[False]*(N*N)
            dq=collections.deque()
            dq.append((i,j,0))
            visited[start]=True
            best=-1
            while dq:
                u,v,d=dq.popleft()
                if u==v:
                    best=2*d
                    break
                if edges[u][v] is not None:
                    cur=2*d+1
                    if best==-1 or cur<best:
                        best=cur
                for (up,vp) in pair_neighbors[u*N+v]:
                    idx=up*N+vp
                    if not visited[idx]:
                        visited[idx]=True
                        dq.append((up,vp,d+1))
            ans[i][j]=best
    out_lines=[' '.join(map(str,row)) for row in ans]
    sys.stdout.write('\n'.join(out_lines))

if __name__=='__main__':
    solve()

