"""
Solution for the problem: generate lexicographically smallest string satisfying T/F constraints with a pattern str2.

Algorithm overview:
1. L = len(str1) + len(str2) - 1. Characters of windows of length m can be set by positions i.
2. For each T at position i, force characters of word at positions [i, i+m-1] to match str2.
   If a conflict occurs (different forced chars), return "".
3. All other positions are free. Initialize them to the smallest letter 'a'.
4. For each F window starting at i, if the current word substring equals str2, then the window is violated.
   Since all forced chars equal str2 for that window, at least one free position must differ.
   We pick the earliest free position within that window and change it to the smallest character that differs from the required char of str2 at that offset.
   If all positions of that window are forced (i.e., can't change), it's impossible.
5. After processing all F windows, the word satisfies every constraint. Return the string.

Complexity: O(L + n*m) where m <= 500 and n <= 10^4, well within limits.
"""

from typing import List


def smallestGeneratedString(str1: str, str2: str) -> str:
    n, m = len(str1), len(str2)
    L = n + m - 1

    word: List[str] = ['?'] * L
    fixed: List[bool] = [False] * L

    # Apply T constraints
    for i, c in enumerate(str1):
        if c == 'T':
            for k, ch in enumerate(str2):
                pos = i + k
                if word[pos] == '?':
                    word[pos] = ch
                    fixed[pos] = True
                elif word[pos] != ch:
                    return ""

    # Default free positions to 'a'
    for idx in range(L):
        if word[idx] == '?':
            word[idx] = 'a'

    # Function to return the smallest character different from a given char
    def next_diff(ch: str) -> str:
        # 'a' is smallest, so if ch != 'a' -> return 'a', else 'b'
        return 'a' if ch != 'a' else 'b'

    # Process F windows
    for i, c in enumerate(str1):
        if c == 'F':
            window_match = True
            for k in range(m):
                pos = i + k
                if word[pos] != str2[k]:
                    window_match = False
                    break
            if not window_match:
                continue
            # Need to change at least one free position
            changed = False
            for k in range(m):
                pos = i + k
                if not fixed[pos] and word[pos] == str2[k]:
                    word[pos] = next_diff(str2[k])
                    changed = True
                    break
            if not changed:
                return ""

    return ''.join(word)

