import collections

def ops(s):
    n=len(s)
    for l in range(n):
        bal=0
        for r in range(l, n):
            bal += 1 if s[r]=='(' else -1
            if bal<0:
                break
            if bal==0:
                sub=s[l:r+1]
                transformed=''.join(')' if ch=='(' else '(' for ch in sub[::-1])
