def feasible(R,B):
    n=R+B
    colors=['R']*R+['B']*B
    # generate all orderings of colors (distinct permutations ignoring identical)
    seen=set()
    for perm in set(itertools.permutations(colors)):
        # build positions via brute search on small board 5x5 maybe
        # We'll search using backtracking
        target=[None]*n
        visited=set()
        def backtrack(i, positions):
            if i==n:
                # check last to first step adjacency
                step_type= ('ortho' if colors[perm[i-1]]=='R' else 'diag')
                r1,c1=positions[i-1]
                r0,c0=positions[0]
                if step_type=='ortho':
                    if abs(r1-r0)+abs(c1-c0)!=1: return False
                else:
                    if abs(r1-r0)==1 and abs(c1-c0)==1:
                        return True
                    else: return False
                # if true, positions found
                return True
            # try places
            for r in range(1,6):
                for c in range(1,6):
                    if (r,c) in visited: continue
                    if i==0:
                        # place anywhere
                        visited.add((r,c))
                        if backtrack(i+1, positions+[(r,c)]):
                            return True
                        visited.remove((r,c))
                    else:
                        step_type=('ortho' if perm[i-1]=='R' else 'diag')
                        pr,pc=positions[i-1]
