def compute2(H,W,bars):
    N=len(bars)
    bars_sorted=sorted([(r,c,l,i) for i,(r,c,l) in enumerate(bars)], key=lambda x:x[0])
    best=[H+1]*(W+1)
    ans=[0]*N
    for r,c,l,i in bars_sorted:
        m=H+1
        for col in range(c,c+l):
            if best[col]<m:
                m=best[col]
        bottom=m-1
        if bottom<r:
            bottom=r
        top=bottom-l+1
        ans[i]=top
        for col in range(c,c+l):
            if bottom>best[col]:
                best[col]=bottom
    return ans

