import bisect, sys

def solve():
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)
    A = [next(it) for _ in range(N)]
    Q = next(it)
    pos = [bisect.bisect_left(A, 2*A[i], lo=i+1) for i in range(N)]
    d = [pos[i]-i for i in range(N)]
    size = 1
    while size < N:
        size <<= 1
    seg = [0]*(2*size)
    for i in range(N):
        seg[size+i] = d[i]
    for i in range(size-1,0,-1):
        seg[i] = seg[2*i] if seg[2*i]>seg[2*i+1] else seg[2*i+1]
    def range_max(l,r):
        l += size; r += size
        res = 0
        while l<=r:
            if l%2==1:
                if seg[l]>res: res=seg[l]
                l+=1
            if r%2==0:
                if seg[r]>res: res=seg[r]
                r-=1
            l//=2; r//=2
        return res
    out=[]
    for _ in range(Q):
        L = next(it)-1; R = next(it)-1
        length = R-L+1
        low=0; high=length//2
        while low<high:
            mid=(low+high+1)//2
            if L+mid>R:
                high=mid-1; continue
            maxd = range_max(L, R-mid)
            if maxd <= mid:
                low=mid
            else:
                high=mid-1
        out.append(str(low))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

