#!/usr/bin/env python3
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    s = data[1].strip()
    # n may be up to 13; length 3^N
    # Define recursive function returning (cost0,mismatch? no cost1)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dp(start, length):
        if length == 1:
            bit = int(s[start])
            return (0 if bit==0 else 1, 0 if bit==1 else 1)
        # split
        third = length // 3
        a0,a1 = dp(start, third)
        b0,b1 = dp(start+third, third)
        c0,c1 = dp(start+2*third, third)
        # compute parent costs
        min0 = 10**9
        min1 = 10**9
        # enumerate output choices for children
        # we can pre compute 8 combos
        # option represent outputs as bits
        for o1 in (0,1):
            for o2 in (0,1):
                for o3 in (0,1):
                    cost = (a0 if o1==0 else a1) + (b0 if o2==0 else b1) + (c0 if o3==0 else c1)
                    # majority output
                    if (o1+o2+o3) <=1: # at most one 1 => majority 0
                        if cost < min0:
                            min0 = cost
                    else: # at least two 1 => majority 1
                        if cost < min1:
                            min1 = cost
        return (min0,min1)
    cost0,cost1 = dp(0, len(s))
    # We want minimal changes to flip final bit. We need to know original final bit
    final_bit = int(s[0])  # wait, final bit after applying operation N times; we don't compute that directly
    # Actually we can compute the result of S by running majority process. Instead easier: we can just compute final_bit via dp? But dp returns cost to make final node 0 or 1. Since we can change bits, but original final bit may be either 0 or 1. Let's compute original majority.
    def original_final(value_str):
        # recursively compute majority
        if len(value_str)==1:
            return value_str
        res = []
        for i in range(0, len(value_str), 3):
            sub = value_str[i:i+3]
            # majority
            if sub.count('1')>=2:
                res.append('1')
            else:
                res.append('0')
        return original_final(''.join(res))
    orig_bit = int(original_final(s))
    # We want to flip final bit, so cost to make final 1 if orig_bit==0 else cost to make final 0
    answer = cost1 if orig_bit==0 else cost0
    print(answer)

if __name__=='__main__':
    solve()

