#!/usr/bin/env python3
import sys
MOD = 998244353

def gen_states(N):
    # generate all nondecreasing arrays dp[0..N] with dp[0]=0 and dp[i]<=i
    states = []
    cur = [0]*(N+1)
    def rec(i):
        if i==N+1:
            states.append(tuple(cur))
            return
        for v in range(cur[i-1], i+1):
            cur[i] = v
            rec(i+1)
    rec(1)
    return states

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0]); M = int(data[1]); S = data[2]
    states = gen_states(N)
    idx_of = {st:i for i,st in enumerate(states)}
    sz = len(states)
    # Precompute transitions for each state and letter
    # Since alphabet size fixed 26, we can store array of next indices
    trans = [[0]*26 for _ in range(sz)]
    for i,st in enumerate(states):
        cur = st
        for li, ch in enumerate('abcdefghijklmnopqrstuvwxyz'):
            new = list(cur)
            for k in range(1, N+1):
                if ch == S[k-1]:
                    val = cur[k-1] + 1
                    if val > new[k]:
                        new[k] = val
                # else new[k] stays cur[k]
            new_tuple = tuple(new)
            trans[i][li] = idx_of[new_tuple]
    # DP over M steps
    cur_vec = [0]*sz
    start_idx = idx_of[tuple([0]+[i for i in range(1,N+1)])]  # state with dp[i]=i
    cur_vec[start_idx] = 1
    for _ in range(M):
        nxt = [0]*sz
        for i, val in enumerate(cur_vec):
            if val==0: continue
            row = trans[i]
            for li in range(26):
                nxt[row[li]] = (nxt[row[li]] + val) % MOD
        cur_vec = nxt
    ans = [0]*(N+1)
    for i,vec_val in enumerate(cur_vec):
        l = states[i][N]
        ans[l] = (ans[l] + vec_val) % MOD
    print(' '.join(str(x%MOD) for x in ans)))

if __name__ == "__main__":
    main()

