    # BFS over states up to depth
    from collections import deque
    start=tuple(pieces)
    # state: tuple sorted of piece positions
    seen={start}
    q=deque([(start,0)])
    while q:
        state,steps=q.popleft()
        if steps>max_ops: return False
        # check condition
        valid=True
