import sys, heapq

def dijkstra(adj, N, start):
    INF = 10**19
    dist=[INF]*(N+1)
    dist[start]=0
    h=[(0,start)]
    while h:
        d,u=heapq.heappop(h)
        if d!=dist[u]: continue
        for v,w in adj[u]:
            nd=d+w
            if nd<dist[v]:
                dist[v]=nd
                heapq.heappush(h,(nd,v))
    return dist

