    target=tuple(range(1,n+1))
    from functools import lru_cache
    @lru_cache(None)
    def dfs(state):
        if state==target:
            return 0
        best=10**9
        for i in range(n-1):
            s=list(state)
            s[i],s[i+1]=s[i+1],s[i]
            new=tuple(s)
            cost=i+1+dfs(new)
            if cost<best:
                best=cost
        return best
    return dfs(tuple(arr))

def greedy_leftmost(arr):
    arr=list(arr)
    n=len(arr)
    total=0
    while True:
        found=False
