import itertools, heapq

def min_cost_dijkstra(arr):
    n=len(arr)
    target=tuple(range(1,n+1))
    start=tuple(arr)
    dist={start:0}
    pq=[(0,start)]
    while pq:
        d,state=heapq.heappop(pq)
        if d!=dist[state]:
            continue
        if state==target:
            return d
        for i in range(n-1):
            s=list(state)
            s[i],s[i+1]=s[i+1],s[i]
            new=tuple(s)
            nd=d+(i+1)
            if new not in dist or nd<dist[new]:
                dist[new]=nd
                heapq.heappush(pq,(nd,new))
