#!/usr/bin/env python3
import sys

def solve():
    MOD = 998244353
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    maxA = max(A)
    # φ array
    phi = list(range(maxA + 1))
    for i in range(2, maxA + 1):
        if phi[i] == i:  # i is prime
            for j in range(i, maxA + 1, i):
                phi[j] -= phi[j] // i
    # Divisors lists
    divs = [[] for _ in range(maxA + 1)]
    for d in range(1, maxA + 1):
        for m in range(d, maxA + 1, d):
            divs[m].append(d)
    # Powers of two
    pow2 = [1] * (N + 1)
    for i in range(1, N + 1):
        pow2[i] = (pow2[i - 1] << 1) % MOD
    # g[d] = sum of 2^{i-1} over previous indices i with A_i % d == 0
    g = [0] * (maxA + 1)
    f = 0
    out_lines = []
    for idx, a in enumerate(A, 1):  # idx is 1-based position
        # Compute S = sum_{i<idx} gcd(A_i, A_idx) * 2^{i-1}
        S = 0
        for d in divs[a]:
            S = (S + phi[d] * g[d]) % MOD
        f = (2 * f + S) % MOD
        out_lines.append(str(f))
        inc = pow2[idx - 1]  # 2^{idx-1}
        for d in divs[a]:
            g[d] = (g[d] + inc) % MOD
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

