from typing import List

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        # Prefix sums of nums and cost
        prefNums = [0]*n
        prefCost = [0]*n
        for i in range(n):
            prefNums[i] = nums[i] + (prefNums[i-1] if i>0 else 0)
            prefCost[i] = cost[i] + (prefCost[i-1] if i>0 else 0)
        # Li Chao tree for min queries
        class LiChao:
            class Line:
                __slots__ = ('m','b')
                def __init__(self, m, b):
                    self.m = m
                    self.b = b
                def get(self, x):
                    return self.m * x + self.b
            class Node:
                __slots__ = ('l','r','mid','left','right','line')
                def __init__(self, l, r):
                    self.l = l
                    self.r = r
                    self.mid = (l + r) >> 1
                    self.left = None
                    self.right = None
                    self.line = None
            def __init__(self, l, r):
                self.root = self.Node(l, r)
            def _add(self, node, new_line):
                l, r, mid = node.l, node.r, node.mid
                if node.line is None:
                    node.line = new_line
                    return
                left_is_better = new_line.get(l) < node.line.get(l)
                mid_is_better = new_line.get(mid) < node.line.get(mid)
                if mid_is_better:
                    node.line, new_line = new_line, node.line
                if r - l == 0:
                    return
                if left_is_better != mid_is_better:
                    if node.left is None:
                        node.left = self.Node(l, mid)
                    self._add(node.left, new_line)
                else:
                    if node.right is None:
                        node.right = self.Node(mid+1, r)
                    self._add(node.right, new_line)
            def add_line(self, m, b):
                self._add(self.root, self.Line(m, b))
            def _query(self, node, x):
                if node is None or node.line is None:
                    return 10**30
                res = node.line.get(x)
                if node.l == node.r:
                    return res
                if x <= node.mid:
                    return min(res, self._query(node.left, x))
                else:
                    return min(res, self._query(node.right, x))
            def query(self, x):
                return self._query(self.root, x)
        INF = 10**30
        # t=1 case
        dp_prev = [INF]*n
        for pos in range(n):
            dp_prev[pos] = (prefNums[pos] + k) * prefCost[pos]
        ans = dp_prev[-1]
        total_pref_nums = prefNums[-1]
        for t in range(2, n+1):
            maxX = -(total_pref_nums + k*n) - 5
            minX = -1
            lichao = LiChao(maxX, minX)
            dp_curr = [INF]*n
            for pos in range(n):
                if pos>0:
                    idx = pos-1
                    lichao.add_line(prefCost[idx], dp_prev[idx])
                x = -(prefNums[pos] + k*t)
                best = lichao.query(x)
                dp_curr[pos] = prefNums[pos]*prefCost[pos] + k*t*prefCost[pos] + best
            ans = min(ans, dp_curr[-1])
            dp_prev = dp_curr
        return ans

