    if not node:
        return (None, None)
    if (node.left.size if node.left else 0) >= k:
        left, right = split(node.left, k)
        node.left = right
        upd(node)
        return (left, node)
    else:
        left, right = split(node.right, k - (1 + (node.left.size if node.left else 0)))
        node.right = left
        upd(node)
        return (node, right)


