    if not a or not b:
        return a or b
    if a.prio > b.prio:
        a.right = merge(a.right, b)
        upd(a)
        return a
    else:
        b.left = merge(a, b.left)
        upd(b)
        return b


def inorder(node, res):
    if not node:
        return
    inorder(node.left, res)
    res.append(str(node.val))
