def brute(W,H,L,R,D,U):
    allowed=set()
    for x in range(W+1):
        for y in range(H+1):
            if not(L<=x<=R and D<=y<=U):
                allowed.add((x,y))
    memo={}
    def count_start(x,y):
        if (x,y) not in allowed:
            return 0
        key=(x,y)
        if key in memo:
