import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    X = int(next(it))
    groups = {1: [], 2: [], 3: []}
    totals = {1:0, 2:0, 3:0}
    for _ in range(N):
        v = int(next(it)); a = int(next(it)); c = int(next(it))
        groups[v].append((c, a))
        totals[v] += a
    # compute dp for each vitamin
    dps = {}
    for v in (1,2,3):
        dp = [-1]*(X+1)
        dp[0] = 0
        for c,a in groups[v]:
            for j in range(X, c-1, -1):
                if dp[j-c] != -1:
                    val = dp[j-c] + a
                    if val > dp[j]:
                        dp[j] = val
        dps[v] = dp
    # upper bound for answer
    ub = min(totals[1], totals[2], totals[3])
    # binary search
    def feasible(t):
        total_cal = 0
        for v in (1,2,3):
            dp = dps[v]
            c_min = X+1
            # find minimal calorie with dp >= t
            for c in range(X+1):
                if dp[c] >= t:
                    c_min = c
                    break
            if c_min == X+1:
                return False
            total_cal += c_min
            if total_cal > X:
                return False
        return total_cal <= X
    lo = 0
    hi = ub+1
    while lo+1 < hi:
        mid = (lo+hi)//2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

