import itertools

def is_bipartite(n,edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    color=[None]*n
    for i in range(n):
        if color[i] is None:
            color[i]=0
            stack=[i]
            while stack:
                u=stack.pop()
                for w in adj[u]:
                    if color[w] is None:
                        color[w]=color[u]^1
                        stack.append(w)
                    elif color[w]==color[u]:
                        return False,None
    return True,color

def grundy(n,edges):
    res=is_bipartite(n,edges)
    if not res[0]:
        return None
    color=res[1]
    key=(tuple(sorted(edges)),tuple(color))
    memo={}
    def dfs(edges_set):
        if edges_set in memo:
            return memo[edges_set]
        # generate allowed moves
        allowed=False
        gset=set(edges_set)
        moves=[]
        for u in range(n):
            for v in range(u+1,n):
                if (u,v) in gset:
                    continue
                # check if adding edge creates odd cycle -> nonlinear: check bipartite after adding
                new_edges=edges_set|{(u,v)}
                ok,color2=is_bipartite(n,new_edges)
                if ok:
                    moves.append(new_edges)
        if not moves:
            memo[edges_set]=0
            return 0
        s=set()
        for new in moves:
            s.add(dfs(new))
        g=0
        while g in s:
            g+=1
        memo[edges_set]=g
        return g
    return dfs(frozenset(edges))

