#!/usr/bin/env python3
import sys
MOD = 998244353

def compute_prime(p, exps):
    """Return sum over all exponent sequences for prime p"""
    total = sum(exps)
    powp = [1] * (total + 1)
    for i in range(1, total + 1):
        powp[i] = powp[i-1] * p % MOD
    # dp0[s] : flag not visited zero yet
    dp0 = [0] * (total + 1)
    dp1 = [0] * (total + 1)
    for s in range(total + 1):
        if s == 0:
            dp1[s] = powp[s]
        else:
            dp0[s] = powp[s]
    for e in exps:
        new0 = [0] * (total + 1)
        new1 = [0] * (total + 1)
        for s in range(total + 1):
            v0 = dp0[s]
            v1 = dp1[s]
            if v0:
                ns = s + e
                if ns <= total:
                    mul = powp[ns]
                    new0[ns] = (new0[ns] + v0 * mul) % MOD
                ns = s - e
                if ns >= 0:
                    mul = powp[ns]
                    if ns == 0:
                        new1[ns] = (new1[ns] + v0 * mul) % MOD
                    else:
                        new0[ns] = (new0[ns] + v0 * mul) % MOD
            if v1:
                ns = s + e
                if ns <= total:
                    mul = powp[ns]
                    new1[ns] = (new1[ns] + v1 * mul) % MOD
                ns = s - e
                if ns >= 0:
                    mul = powp[ns]
                    new1[ns] = (new1[ns] + v1 * mul) % MOD
        dp0, dp1 = new0, new1
    return sum(dp1) % MOD

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N-1)]
    # generate primes up to 1000
    LIM = 1000
    is_prime = [True]*(LIM+1)
    is_prime[0] = is_prime[1] = False
    for i in range(2,int(LIM**0.5)+1):
        if is_prime[i]:
            step = i
            start = i*i
            for j in range(start, LIM+1, step):
                is_prime[j] = False
    primes = [p for p in range(2, LIM+1) if is_prime[p]]
    # build exponent lists per prime
    prime_exps = {}
    for a in A:
        x = a
        for p in primes:
            if p*p > x:
                break
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in prime_exps:
                    prime_exps[p] = [0]*(N-1)
                prime_exps[p][-1] = e  # temporarily store? but need position
        # will handle positions separately
    # The above naive approach not enough; we need per prime full list
    # We reconstruct properly
    prime_exps_full = {}
    for p in primes:
        exps = [0]*(N-1)
        for idx,a in enumerate(A):
            val = a
            cnt = 0
            while val % p == 0:
                val //= p
                cnt += 1
            exps[idx] = cnt
        if any(exps):
            prime_exps_full[p] = exps
    # compute result
    ans = 1
    for p, exps in prime_exps_full.items():
        ans = ans * compute_prime(p, exps) % MOD
    print(ans)

if __name__ == "__main__":
    solve()

import random, sys
from itertools import combinations, permutations

def pair_cost(a,b):
    return max(a[0]+b[0], a[1]+b[1], a[2]+b[2])

def greedy(items,K):
    remaining=list(range(len(items)))
    total=0
    for _ in range(K):
        best_pair=None
        best_val=-1
        for i in range(len(remaining)):
            for j in range(i+1,len(remaining)):
                val=pair_cost(items[remaining[i]], items[remaining[j]])
                if val>best_val:
                    best_val=val
                    best_pair=(i,j)
        total+=best_val
        i,j=best_pair
        # remove higher index first
        for idx in sorted([i,j], reverse=True):
            remaining.pop(idx)
    return total

def brute_opt(items,K):
    N=len(items)
    best=-1
    indices=list(range(N))
    for chosen in combinations(indices, 2*K):
        def backtrack(rem,pairs):
            nonlocal best
            if not rem:
                val=0
                for a,b in pairs:
                    val+=pair_cost(items[a], items[b])
                best=max(best,val)
                return
            a=rem[0]
            for i in range(1,len(rem)):
                b=rem[i]
                backtrack(rem[1:i]+rem[i+1:], pairs+[(a,b)])
        backtrack(list(chosen), [])
    return best

