from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0
        # original max subarray sum (Kadane)
        max_ending = max_global = nums[0]
        for x in nums[1:]:
            max_ending = max(x, max_ending + x)
            if max_ending > max_global:
                max_global = max_ending
        answer = max_global
        # prefix sums
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i+1] = pref[i] + nums[i]
        # count occurrences per value
        value_positions = {}
        for i,v in enumerate(nums):
            value_positions.setdefault(v, []).append(i)
        for val, pos_list in value_positions.items():
            if len(pos_list) == n:
                # removal would empty array, skip
                continue
            count = 0
            min_val = 0  # corresponds to prefix before first element
            current_max = None
            # iterate through positions in order
            # need to know prefix sum at each index r and cumulative count
            # we can iterate r from 0 to n-1
            for r in range(n):
                if nums[r] == val:
                    count += 1
                cur_val = pref[r+1] - val * count
                if current_max is None:
                    current_max = cur_val - min_val
                else:
                    if cur_val - min_val > current_max:
                        current_max = cur_val - min_val
                if cur_val < min_val:
                    min_val = cur_val
            if current_max is not None and current_max > answer:
                answer = current_max
        return answer

