    data = list(map(int, sys.stdin.read().split()))
    it = iter(data)
    N = next(it)
    L = [0]*N
    R = [0]*N
    for i in range(N):
        L[i] = next(it)
        R[i] = next(it)
    Q = next(it)
    queries = [next(it) for _ in range(Q)]
    MAX_X = 500000

    class BIT:
        __slots__=('n','bit')
        def __init__(self,n):
            self.n = n
            self.bit = [0]*(n+2)
        def add(self,i,v):
            while i <= self.n:
                self.bit[i] += v
                i += i & -i
        def sum(self,i):
            s = 0
            while i > 0:
                s += self.bit[i]
                i -= i & -i
            return s

    bit = BIT(MAX_X)

    def f(x):
        return x + bit.sum(x)

