        l = L[i]
        r = R[i]
        lo, hi = 1, MAX_X
        left = -1
        while lo <= hi:
            mid = (lo + hi) >> 1
            if f(mid) >= l:
                left = mid
                hi = mid - 1
            else:
                lo = mid + 1
        if left == -1:
