def kth_alternating(n,k):
    total_odd=(n+1)//2
    total_even=n//2
    INF=10**18
    @functools.lru_cache(None)
    def count(a,b,prev):
        if a==0 and b==0:
            return 1
        total=0
        if prev is None:
            if a>0:
                total+=count(a-1,b,1)
            if b>0:
                total+=count(a,b-1,0)
        else:
            if prev==0:  # last even -> need odd
                if a>0:
                    total+=count(a-1,b,1)
            else:  # prev==1 odd -> need even
                if b>0:
                    total+=count(a,b-1,0)
        return min(total,INF)
    used=[False]*(n+1)
    a_rem=total_odd
    b_rem=total_even
    prev=None
    ans=[]
    for pos in range(n):
        found=False
        for num in range(1,n+1):
            if used[num]:
                continue
            parity=num%2
            if prev is not None and parity==prev:
                continue
            new_a=a_rem-(parity==1)
            new_b=b_rem-(parity==0)
            if new_a<0 or new_b<0:
                continue
            cnt=count(new_a,new_b,parity)
            if k>cnt:
                k-=cnt
            else:
                ans.append(num)
                used[num]=True
                a_rem=new_a
                b_rem=new_b
                prev=parity
                found=True
                break
        if not found:
            return []
    return ans

