#!/usr/bin/env python3
import sys
import bisect

def allowed_intervals(n, forbidden):
    forb=sorted(forbidden)
    intervals=[]
    prev=0
    for f in forb:
        if f-1>=prev+1:
            intervals.append((prev+1,f-1))
        prev=f
    if n>=prev+1:
        intervals.append((prev+1,n))
    return intervals

def count_pairs_with_sum(sum_val, row_ints, col_ints, N):
    intervals=[]
    for cl,cr in col_ints:
        lo=sum_val-cr
        hi=sum_val-cl
        if lo>hi:
            lo,hi=hi,lo
        lo=max(lo,1); hi=min(hi,N)
        if lo<=hi:
            intervals.append((lo,hi))
    if not intervals:
        return 0
    intervals.sort()
    merged=[]
    cur_l,cur_r=intervals[0]
    for l,r in intervals[1:]:
        if l<=cur_r+1:
            cur_r=max(cur_r,r)
        else:
            merged.append((cur_l,cur_r))
            cur_l,cur_r=l,r
    merged.append((cur_l,cur_r))
    cnt=0
    for rl,rr in row_ints:
        for l,r in merged:
            lo=max(rl,l); hi=min(rr,r)
            if lo<=hi:
                cnt+=hi-lo+1
    return cnt

def count_pairs_with_diff(diff_val, row_ints, col_ints, N):
    intervals=[]
    for cl,cr in col_ints:
