    merged.append((cur_l,cur_r))
    cnt=0
    for rl,rr in row_ints:
        for l,r in merged:
            lo=max(rl,l); hi=min(rr,r)
            if lo<=hi:
                cnt+=hi-lo+1
    return cnt

def is_point_allowed(val, intervals):
    lo,hi=0,len(intervals)
    while lo<hi:
        mid=(lo+hi)//2
        l,r=intervals[mid]
        if val<l:
            hi=mid
        elif val>r:
            lo=mid+1
        else:
            return True
    return False

def solve():
    data=sys.stdin.read().strip().split()
    if not data:
        return
    it=iter(data)
    N=int(next(it))
    M=int(next(it))
    rows=set(); cols=set(); sums=set(); diffs=set()
