    sum_pairs=sum(count_pairs_with_sum(s,row_ints,col_ints,N) for s in sums)
    diff_pairs=sum(count_pairs_with_diff(d,row_ints,col_ints,N) for d in diffs)
    both=0
    for s in sums:
