def lis_len(seq):
    from bisect import bisect_left
    dp=[]
    for x in seq:
        i=bisect_left(dp,x)
        if i==len(dp): dp.append(x)
        else: dp[i]=x
    return len(dp)

def lds_len(seq):
    from bisect import bisect_left
    dp=[]
    for x in seq:
        i=bisect_left(dp,-x)
        if i==len(dp): dp.append(-x)
        else: dp[i]=-x
    return len(dp)

