import sys

def solve():
    input=sys.stdin.readline
    N=int(input().strip())
    adj=[[] for _ in range(N)]
    for _ in range(N-1):
        u,v=map(int,input().split())
        u-=1;v-=1
        adj[u].append(v)
        adj[v].append(u)
    deg=[len(adj[i]) for i in range(N)]
    leaf_adj=[0]*N
    for i in range(N):
        cnt=0
        for nb in adj[i]:
            if deg[nb]==1:
                cnt+=1
        leaf_adj[i]=cnt
    max_keep=0
    for c in range(N):
        if deg[c]<2: # need center degree at least 2 to have x>=1
            continue
        L=[]
        for nb in adj[c]:
            if leaf_adj[nb]>0:
                L.append(leaf_adj[nb])
        if not L:
            continue
        L.sort(reverse=True)
        kmax=len(L)
        for k in range(1,kmax+1):
            y=L[k-1]
            if y==0:
                continue
            keep=1 + k*(1+y)
            if keep>max_keep:
                max_keep=keep
    # Edge case: maybe the whole tree is already snowflake; center might have deg>=2.
    if max_keep==0:
        # fallback: tree might be already snowflake with center having deg 1? Actually impossible
        max_keep=1
    print(N-max_keep)

if __name__=='__main__':
    solve()

