import random, itertools

def is_snowflake(nodes, edges):
    # nodes subset list of 0..N-1, edges list of tuple
    N=len(set(edges))
    # reconstruct degrees
    deg={v:0 for v in nodes}
    for a,b in edges:
        if a in nodes and b in nodes:
            deg[a]+=1
            deg[b]+=1
    # need to find center, middle and leaf
    # find node with degree>=1 as center
    # brute try each node as center in nodes
    for c in nodes:
        # neighbors of c among nodes
        neigh=[b for x,y in edges if (x==c and y in nodes) or (y==c and x in nodes)]
        # but compute adjacency quickly
        up=set()
        for a,b in edges:
            if a==c and b in nodes: up.add(b)
            if b==c and a in nodes: up.add(a)
        neigh=list(up)
        x=len(neigh)
        if x==0: continue
        # For each neighbor m
        ok=True
        ys=None
        for m in neigh:
            # neighbors of m excluding c
            upm=set()
            for a,b in edges:
                if a==m and b in nodes and b!=c: upm.add(b)
                if b==m and a in nodes and a!=c: upm.add(a)
            y=len(upm)
            if y<1: ok=False; break
            if ys is None: ys=y
            else: ys=min(ys,y)
        if not ok: continue
        # Now check that all other nodes are leaves attached to some m (i.e., not in center or neigh nor their children)
        for v in nodes:
            if v==c: continue
            if v in neigh: continue
            # v must be leaf attached to some m
            # find its parent
            parent=None
            for a,b in edges:
                if (a==v and b in neigh) or (b==v and a in neigh):
                    parent=a if a in neigh else b
                    break
            if parent is None: ok=False; break
            # ensure its degree is 1
            degv=sum(1 for a,b in edges if a==v or b==v and {a,b}<=set(nodes))
            if degv!=1: ok=False; break
        if ok:
            return True
    return False

def brute_min_del(tree_edges, N):
    nodes=list(range(N))
    best=N
    for r in range(N+1):
        for subset in itertools.combinations(nodes,r):
            remaining=set(subset)
            if not remaining: continue
            if len([e for e in tree_edges if e[0] in remaining and e[1] in remaining])!=len(remaining)-1:
