import random, itertools

def is_snowflake(nodes, edges):
    # nodes set
    # rebuild adjacency
    adj={v:set() for v in nodes}
    for a,b in edges:
        if a in nodes and b in nodes:
            adj[a].add(b)
            adj[b].add(a)
    for c in nodes:
        neigh=[b for b in adj[c]]
        if not neigh: continue
        # gather leaf counts
        ok=True
        min_y=None
        for m in neigh:
            children=[b for b in adj[m] if b!=c]
            if not children:
                ok=False;break
            # all children must be leaves in induced graph
            for col in children:
                if len(adj[col])!=1:
                    ok=False;break
            if not ok:break
            if min_y is None: min_y=len(children)
            else: min_y=min(min_y,len(children))
        if not ok: continue
        # check other nodes leaves
        for v in nodes:
            if v==c or v in neigh: continue
            if len(adj[v])!=1:
                ok=False;break
        if ok: return True
    return False

def brute_min_del(N,edges):
    nodes=list(range(N))
    best=N
    for r in range(N+1):
        for comb in itertools.combinations(nodes,r):
            rem=set(comb)
            if not rem: continue
            # edges in induced
            ind=[e for e in edges if e[0] in rem and e[1] in rem]
            if len(ind)!=len(rem)-1: continue
            if is_snowflake(rem,edges):
                best=min(best,N-len(rem))
    return best

