import sys


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    # Binary search maximum K
    def can(K):
        # Return True if we can make K kagamimochi
        if K == 0:
            return True
        # pair smallest K with largest K
        for i in range(K):
            if A[i] * 2 > A[N-K+i]:
                return False
        return True
    lo, hi = 0, N//2
    while lo < hi:
        mid = (lo + hi + 1)//2
        if can(mid):
            lo = mid
        else:
            hi = mid-1
    print(lo)

if __name__ == "__main__":
    solve()

