def feasible(points, m, T):
    n=len(points)
    need=[(T + p -1)//p for p in points]
    # find R
    R=-1
    for i, val in enumerate(need):
        if val>0:
            R=i
    if R==-1:
        return False
    # check prefix positivity
    for i in range(R+1):
        if need[i]==0:
            return False
    for i in range(R+1, n):
        if need[i]!=0:
            return False
    if need[0]==0: return False
    e=[0]*R
    e[0]=need[0]-1
    if e[0]<0: return False
    for i in range(1,R):
        e[i]=need[i]-e[i-1]
        if e[i]<0: return False
    # check last condition
    if e[R-1]!=need[R]:
        return False
    sum_e=sum(e)
    return sum_e<=m-1


