def solve_with_dfs(grid, H, W, K):
    cells = []
    idx_grid = [[-1]*W for _ in range(H)]
    idx=0
    for i in range(H):
        for j in range(W):
            if grid[i][j]=='.':
                cells.append((i,j))
                idx_grid[i][j]=idx
                idx+=1
    N=len(cells)
    if N < K+1:
        return 0
    adj=[[] for _ in range(N)]
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    for t,(i,j) in enumerate(cells):
        for di,dj in dirs:
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and idx_grid[ni][nj]!=-1:
                adj[t].append(idx_grid[ni][nj])
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(cur, visited_mask, depth):
        if depth==K+1:
            return 1
        total=0
        for nb in adj[cur]:
            if not (visited_mask>>nb)&1:
                total+=dfs(nb, visited_mask|1<<nb, depth+1)
        return total
    total_paths=0
    for start in range(N):
        total_paths+=dfs(start, 1<<start, 1)
    return total_paths

