import itertools, math

def expected_cover_path(L):
    # nodes 0..L
    from functools import lru_cache
    @lru_cache(None)
    def f(pos, visited_mask):
        if visited_mask==(1<<(L+1))-1:
            return 0
        # neighbors
        neigh=[]
        if pos>0:
            neigh.append(pos-1)
        if pos<L:
            neigh.append(pos+1)
        prob=1/len(neigh)
        total=0
        for nxt in neigh:
            new_mask=visited_mask| (1<<nxt)
            total+=f(nxt,new_mask)
        return 1+total*prob
    return f(0,1)

