def compute_all(maxN,maxM):
    from fractions import Fraction
    res={}
    for N in range(1,maxN+1):
        for M in range(1,maxM+1):
            V=N*M+1
            neighbors=[[] for _ in range(V)]
            for i in range(1,V):
                p=max(i-N,0)
                neighbors[i].append(p)
                neighbors[p].append(i)
            all_mask=(1<<V)-1
            states=[]
            idx={}
            for pos in range(V):
                for mask in range(1<<V):
                    if not (mask>>pos)&1: continue
                    if mask==all_mask: continue
                    key=(pos,mask)
                    if key not in idx:
                        idx[key]=len(states)
                        states.append(key)
            n=len(states)
            A=[[Fraction(0) for _ in range(n)] for _ in range(n)]
            b=[Fraction(1) for _ in range(n)]
            for i,(pos,mask) in enumerate(states):
                A[i][i]=Fraction(1)
                deg=len(neighbors[pos])
                for nxt in neighbors[pos]:
                    newmask=mask | (1<<nxt)
                    if newmask==all_mask:
                        continue
                    j=idx[(nxt,newmask)]
                    A[i][j]-=Fraction(1,deg)
            # Gaussian elimination
            for i in range(n):
                piv=i
                while A[piv][i]==0:
                    piv+=1
                if piv!=i:
                    A[i],A[piv]=A[piv],A[i]
                    b[i],b[piv]=b[piv],b[i]
                inv=A[i][i]
                for j in range(i,n):
                    A[i][j]/=inv
                b[i]/=inv
                for k in range(n):
                    if k==i: continue
                    factor=A[k][i]
                    if factor==0: continue
                    for j in range(i,n):
                        A[k][j]-=factor*A[i][j]
                    b[k]-=factor*b[i]
            res[(N,M)]=b[idx[(0,1)]]
    return res

