def max_non_crossing(arr):
    N=len(arr)
    from functools import lru_cache
    @lru_cache(None)
    def dfs(l,r):
        if l>r: return 0
        if l==r: return 0
        best=0
        # pair l with any k where k-l is odd and l<k<=r
        for k in range(l+1,r+1,2):
            cost = abs(arr[l]-arr[k]) + dfs(l+1,k-1) + dfs(k+1,r)
            if cost>best: best=cost
        return best
    return dfs(0,N-1)

