import sys
from typing import List, Set, Tuple


def solve(inp: str) -> str:
    data = inp.strip().split()
    if not data:
        return ""
    N = int(data[0])
    s = data[1]
    t = data[2]
    assert len(s)==N and len(t)==N
    # mapping from source to set of targets
    target_of = {}  # dict char -> char
    edges_set: Set[Tuple[str,str]] = set()
    for ch_s, ch_t in zip(s,t):
        if ch_s == ch_t:
            continue
        if ch_s in target_of:
            if target_of[ch_s] != ch_t:
                return "-1"
        else:
            target_of[ch_s] = ch_t
            edges_set.add((ch_s,ch_t))
    # Build graph adjacency
    adj = {}  # char -> char
    for a,b in edges_set:
        adj[a] = b
    # DFS to count cycles
    state = {c:0 for c in adj}
    cycles = 0
    def dfs(u:str, stack:Set[str]):
        nonlocal cycles
        stack.add(u)
        state[u] = 1
        v = adj.get(u)
        if v:
            if state.get(v,0)==0:
                dfs(v, stack)
            elif state.get(v,0)==1:
                cycles += 1
        state[u] = 2
        stack.remove(u)
    for node in adj:
        if state.get(node,0)==0:
            dfs(node,set())
    ans = len(edges_set)+cycles
    return str(ans)

