import sys

def solve():
    data=sys.stdin.read().strip().split()
    if not data:
        return
    N=int(data[0])
    s=data[1]
    t=data[2]
    # Map each source char to the set of target chars appearing where source char is at that position
    target_map={}
    for cs,ct in zip(s,t):
        if cs not in target_map:
            target_map[cs]=set()
        target_map[cs].add(ct)
    # If any source char has more than one target distinct values -> impossible
    for source, targets in target_map.items():
        if len(targets)>1:
            print(-1)
            return
    # Build directed edges for swaps: only where source!=target
    edges=set()
    for source, targets in target_map.items():
        for tchar in targets:
            if source!=tchar:
                edges.add((source,tchar))
    # Now we need to count unique edges and number of cycles in the graph defined by edges
    # Construct adjacency only for edges
    adj={}
    for a,b in edges:
        adj[a]=b
    # DFS to find cycles
    visited={}
    def dfs(u, stack):
        visited[u]=1
        stack.add(u)
        v=adj.get(u)
        if v:
            if visited.get(v,0)==0:
                dfs(v, stack)
            elif visited.get(v,0)==1:
                # found cycle
                nonlocal cycle_cnt
                cycle_cnt+=1
        visited[u]=2
        stack.remove(u)
    cycle_cnt=0
    for node in adj:
        if visited.get(node,0)==0:
            dfs(node,set())
    # minimal operations = number of edges + number of cycles
    ans=len(edges)+cycle_cnt
    print(ans)

if __name__=="__main__":
    solve()

