def count(nums):
    n=len(nums)
    res=0
    for mask1 in range(1,1<<n):
        seq1=[nums[i] for i in range(n) if mask1>>i &1]
        gcd1=seq1[0]
        for x in seq1[1:]:
            gcd1=math.gcd(gcd1,x)
        for mask2 in range(1,1<<n):
