    N=len(A)
    pairs=[]
    for i in range(N-1):
        if A[i]==A[i+1]:
            pairs.append(i)
    if not pairs:
        return 0
    max_len=0
    l=0
    freq={}
    for r in range(len(pairs)):
        p=pairs[r]
        if r>0 and pairs[r]-pairs[r-1]>2:
            l=r
            freq={}
        val=A[p]
        while val in freq:
            val_left=A[pairs[l]]
