def formula(N, seq):
    # simple sum distances between same hand consecutive targets
    posL=1
    posR=2
    total=0
    for H,T in seq:
        if H=='L':
            total+=min((T-posL)%N,(posL-T)%N)
            posL=T
        else:
            total+=min((T-posR)%N,(posR-T)%N)
            posR=T
    return total

