from typing import List


def longest_v_shaped(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0
    n, m = len(grid), len(grid[0])
    dirs = [(-1,-1), (-1,1), (1,1), (1,-1)]  # UL, UR, DR, DL
    # Precompute dp for expectations 0 and 2 for each direction
    dp0_list = []  # expectation 0
    dp2_list = []  # expectation 2
    for dir_idx, (dx, dy) in enumerate(dirs):
        dp0 = [[0]*m for _ in range(n)]
        dp2 = [[0]*m for _ in range(n)]
        # Determine iteration order
        if dx == 1 and dy == 1:
            i_range = range(n-1, -1, -1)
            j_range = range(m-1, -1, -1)
        elif dx == 1 and dy == -1:
            i_range = range(n-1, -1, -1)
            j_range = range(m)
        elif dx == -1 and dy == 1:
            i_range = range(n)
            j_range = range(m-1, -1, -1)
        else:  # dx == -1 and dy == -1
            i_range = range(n)
            j_range = range(m)
        for i in i_range:
            for j in j_range:
                val = grid[i][j]
                ni = i + dx
                nj = j + dy
                if val == 0:
                    if 0 <= ni < n and 0 <= nj < m:
                        dp0[i][j] = 1 + dp2[ni][nj]
                    else:
                        dp0[i][j] = 1
                else:
                    dp0[i][j] = 0
                if val == 2:
                    if 0 <= ni < n and 0 <= nj < m:
                        dp2[i][j] = 1 + dp0[ni][nj]
                    else:
                        dp2[i][j] = 1
                else:
                    dp2[i][j] = 0
        dp0_list.append(dp0)
        dp2_list.append(dp2)
    best = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] != 1:
                continue
            for dir_idx, (dx, dy) in enumerate(dirs):
                cur_i, cur_j = i, j
                step_idx = 0
                while True:
                    # decide best with turn at current cell
                    idx_next = step_idx + 1
                    next_exp = 2 if idx_next % 2 == 1 else 0
                    next_dir_idx = (dir_idx + 1) % 4
                    ndx, ndy = dirs[next_dir_idx]
                    ni = cur_i + ndx
                    nj = cur_j + ndy
                    if 0 <= ni < n and 0 <= nj < m:
                        total_len = step_idx + 1 + (dp2_list[next_dir_idx][ni][nj] if next_exp == 2 else dp0_list[next_dir_idx][ni][nj])
                        if total_len > best:
                            best = total_len
                    else:
                        # no turn possible, straight only upto current
                        if step_idx + 1 > best:
                            best = step_idx + 1
                    # advance in same direction
                    step_idx += 1
                    next_i = cur_i + dx
                    next_j = cur_j + dy
                    if not (0 <= next_i < n and 0 <= next_j < m):
                        break
                    # pattern check for next cell
                    if step_idx == 1:
                        if grid[next_i][next_j] != 2:
                            break
                    else:
                        expected = 2 if step_idx % 2 == 1 else 0
                        if grid[next_i][next_j] != expected:
                            break
                    cur_i, cur_j = next_i, next_j
                    continue
    return best

