import sys
MOD=10**9+7

def solve():
    import sys
    s=sys.stdin.read().strip()
    if not s:
        return
    n=len(s)
    move_map={'F':0,'W':1,'E':2}
    a=[move_map[ch] for ch in s]
    # diff_dir[a][b] : Bob - Alice points from this round
    # Using rules: F beats E, W beats F, E beats W
    diff_dir=[[0]*3 for _ in range(3)]
    # Initialize with 0
    for ai in range(3):
        for bi in range(3):
            if ai==bi:
                diff_dir[ai][bi]=0
            elif (ai,bi)==(2,0): # Bob F (0) beats Alice E (2) -> Bob +1
                diff_dir[ai][bi]=1
            elif (ai,bi)==(0,1): # Bob W beats Alice F -> +1
                diff_dir[ai][bi]=1
            elif (ai,bi)==(1,2): # Bob E beats Alice W -> +1
                diff_dir[ai][bi]=1
            else:
                diff_dir[ai][bi]=-1
    # dp[move][diff+offset]
    offset=n
    size=2*n+1
    dp_prev=[[0]*size for _ in range(3)]
    # first round
    for bm in range(3):
        d=diff_dir[a[0]][bm]
        dp_prev[bm][d+offset]+=1
    # process remaining rounds
    for i in range(1,n):
        dp_cur=[[0]*size for _ in range(3)]
        ai=a[i]
        for last in range(3):
            for dd in range(size):
                cnt=dp_prev[last][dd]
                if cnt==0:
                    continue
                cur_diff=dd-offset
                for bm in range(3):
                    if bm==last:
                        continue
                    nd=cur_diff+diff_dir[ai][bm]
                    dp_cur[bm][nd+offset]=(dp_cur[bm][nd+offset]+cnt)%MOD
        dp_prev=dp_cur
    # sum results with diff>0
    ans=0
    for last in range(3):
        for dd in range(offset+1,size):
            ans=(ans+dp_prev[last][dd])%MOD
    print(ans)

if __name__=='__main__':
    solve()

