#!/usr/bin/env python3
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(N)]
    K = int(next(it))
    queries = [(int(next(it)), int(next(it))) for _ in range(K)]
    out_lines = []
    for X, Y in queries:
        s = 0
        for i in range(X):
            ai = A[i]
            for j in range(Y):
                s += abs(ai - B[j])
        out_lines.append(str(s))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
